import { defineI18n } from 'fumadocs-core/i18n';

/**
 * RU is the default locale served at the docs root (`/docs/...`),
 * EN lives under the `/docs/en/...` prefix (`hideLocale: 'default-locale'`).
 *
 * The app is a static export, so the fumadocs i18n middleware (which only
 * performs Accept-Language redirects on server deployments) is intentionally
 * NOT installed: every URL is served as a plain file, and in-app links are
 * generated by the source in the correct prefixed/unprefixed form.
 *
 * `parser: 'dir'` groups content by locale folders:
 * `content/docs/ru/**` and `content/docs/en/**`.
 */
export const i18n = defineI18n({
  defaultLanguage: 'ru',
  languages: ['ru', 'en'],
  hideLocale: 'default-locale',
  parser: 'dir',
});
